    this.renderHUD();

    if (delta > 0) {
      audio.playHopeDown();
      return `<div class="stat-change-notify stat-down">▲ +${delta}% Dolor en la pierna (${reason})</div>`;
    } else if (delta < 0) {
      audio.playHopeUp();
      return `<div class="stat-change-notify stat-up">▼ ${Math.abs(delta)}% Dolor en la pierna (${reason})</div>`;
    }
