    filtro_lectores_acceso: {
      render: (game) => {
        game.setAscii("filtroLectoresCandado");
        game.renderHUD();

        const validateSecret = (val) => {
          if (!val) return false;
          const clean = val.toLowerCase().trim()
            .normalize("NFD").replace(/[\u0300-\u036f]/g, "");
          return clean === "15" || clean === "quince" || clean === "15 anos" || clean === "quince anos";
        };

        game.addStoryBlock({
          title: "🔐 PUZLE DE ACCESO PARA LECTORES · COMPROBACIÓN DE IDENTIDAD",
          text: `
            <div style="background: rgba(15, 23, 42, 0.9); border: 2px solid #fbbf24; padding: 24px; border-radius: 12px; margin-bottom: 18px; color: #f8fafc; text-align: center;">
              <span style="font-size: 2.2rem;">📖</span>
              <h3 style="color: #fbbf24; margin: 8px 0; font-size: 1.3rem;">PUZLE DE ACCESO PARA LECTORES · COMPROBACIÓN DE IDENTIDAD</h3>
              <p style="color: #cbd5e1; font-size: 0.95rem; font-style: italic; margin-bottom: 16px;">
                Este capítulo inédito está reservado exclusivamente para quienes han leído la novela original. Para desbloquear el acceso, responde a la siguiente pregunta:
              </p>

              <div style="background: rgba(30, 41, 59, 0.7); border: 1px solid #475569; padding: 16px; border-radius: 8px; margin-bottom: 18px; font-size: 1.05rem; font-weight: bold; color: #fef08a;">
                ¿Qué edad tenía el hermano de Carlos cuando falleció?
              </div>

              <div style="margin: 16px 0;">
                <input type="text" id="filtro-lectores-input" placeholder="Introduce tu respuesta..." style="padding: 10px 14px; font-size: 1.05rem; border-radius: 6px; border: 2px solid #3b82f6; background: #020617; color: #ffffff; width: 75%; max-width: 260px; text-align: center; outline: none;">
                <div style="margin-top: 12px;">
                  <button id="filtro-lectores-btn" class="choice-btn" style="width: auto; display: inline-block; padding: 10px 24px; font-size: 0.95rem; background: #2563eb; color: #fff; font-weight: bold;">
                    Comprobar Respuesta 🔓
                  </button>
                </div>
                <div id="filtro-lectores-attempts" style="margin-top: 10px; font-size: 0.85rem; color: #94a3b8;">
                  Intentos restantes: <span id="intentos-count" style="font-weight: bold; color: #38bdf8;">${Math.max(0, 3 - (game.state.intentosFiltroLectores || 0))}</span> / 3
                </div>
                <div id="filtro-lectores-feedback" style="margin-top: 12px; font-weight: bold; font-size: 0.95rem; min-height: 24px;"></div>
              </div>

              <div style="margin-top: 20px; padding-top: 16px; border-top: 1px solid rgba(255, 255, 255, 0.15);">
                <p style="font-size: 0.88rem; color: #94a3b8; margin-bottom: 10px;">
                  ¿Aún no has leído la novela o no recuerdas este detalle íntimo? Puedes adquirir el libro aquí:
                </p>
                <a href="https://www.amazon.es/dp/B0GXS3C7X2" target="_blank" rel="noopener noreferrer" style="display: inline-flex; align-items: center; gap: 8px; background: #d97706; color: #ffffff; padding: 8px 18px; border-radius: 6px; text-decoration: none; font-weight: bold; font-size: 0.9rem; transition: background 0.2s;">
                  🛒 Comprar «El Diario del Apocalipsis» en Amazon ↗
                </a>
              </div>
            </div>
          `,
          type: "carlos-voice"
        });

        // Método expuesto para permitir verificación tanto por DOM como por pruebas automatizadas
        game.verificarRespuestaFiltro = (val) => {
          const feedbackEl = document.getElementById("filtro-lectores-feedback");
          const countEl = document.getElementById("intentos-count");

          if (validateSecret(val)) {
            if (feedbackEl) {
              feedbackEl.style.color = "#10b981";
              feedbackEl.textContent = "¡Respuesta correcta! Desbloqueando Escena Extra 1...";
            }
            audio.playHopeUp();
            game.state.flags.filtroLectoresDesbloqueado = true;
            game.trackEvent("filtro_lectores_superado", { intentos: game.state.intentosFiltroLectores || 0 });
            game.loadScene("escena_extra1_inicio");
            return true;
          } else {
            game.state.intentosFiltroLectores = (game.state.intentosFiltroLectores || 0) + 1;
            const remaining = Math.max(0, 3 - game.state.intentosFiltroLectores);
            if (countEl) countEl.textContent = remaining;

            audio.playHopeDown();
            if (remaining <= 0) {
              if (feedbackEl) {
                feedbackEl.style.color = "#ef4444";
                feedbackEl.textContent = "Has agotado los 3 intentos. Reiniciando la partida...";
              }
              game.restart();
            } else {
              if (feedbackEl) {
                feedbackEl.style.color = "#ef4444";
                feedbackEl.textContent = `Respuesta incorrecta. Te queda${remaining === 1 ? '' : 'n'} ${remaining} intento${remaining === 1 ? '' : 's'}.`;
              }
            }
            return false;
          }
        };

        setTimeout(() => {
          const inputEl = document.getElementById("filtro-lectores-input");
          const btnEl = document.getElementById("filtro-lectores-btn");

          if (btnEl && inputEl) {
            btnEl.addEventListener("click", () => {
              game.verificarRespuestaFiltro(inputEl.value);
            });

            inputEl.addEventListener("keydown", (e) => {
              if (e.key === "Enter") btnEl.click();
            });
          }
        }, 50);

        game.renderChoices([
            {
              key: "[1]",
              text: "🛒 📖 Comprar «El Diario del Apocalipsis» en Amazon (Abre en nueva pestaña)",
              action: () => {
                window.open("https://www.amazon.es/dp/B0GXS3C7X2", "_blank");
              }
            },
            {
              key: "[2]",
              text: "🔄 🌅 Volver al inicio (Soria)",
              action: () => game.restart()
            }
        ], "PUZLE DE ACCESO EXCLUSIVO PARA LECTORES");
      }
    },

